abstract class Base { abstract area(): number; d() { return this.area(); } }
class Rect extends Base { w: number; constructor(w: number) { super(); this.w = w; } area() { return this.w * 2; } }
class Sq extends Base { area(): number { return 4; } }
function main(): void { console.log(new Rect(2).d(), new Sq().d()); }
